// ---- helpers for the navigation widgets ----
const tab = (label, icon, page, startHere, x, v = 'page') => ({ name: label + ' Tab', ui: true, anchor: 'center', x, y: 0, shape: { type: 'rect', w: 80, h: 60, radius: 14, fill: '' },
  behaviors: [{ type: 'navItem', page, var: v, startHere, activeColor: 'rgba(79,163,255,0.22)', idleColor: '', dimIdle: true, message: '' }],
  children: [
    { name: label + ' Icon', ui: true, anchor: 'center', x: 0, y: -9, sprite: { src: 'art:ui-' + icon, w: 26, h: 26 } },
    { name: label + ' Label', ui: true, anchor: 'center', x: 0, y: 18, text: { value: label, size: 12, color: '#ffffff', weight: '700' } },
  ] });
const row = (label, icon, page, y, startHere = false) => ({ name: label + ' Item', ui: true, anchor: 'center', x: 0, y, shape: { type: 'rect', w: 228, h: 50, radius: 12, fill: '' },
  behaviors: [{ type: 'navItem', page, var: 'page', startHere, activeColor: 'rgba(79,163,255,0.25)', idleColor: '', dimIdle: false, message: '' }],
  children: [
    { name: label + ' Item Icon', ui: true, anchor: 'left', x: 30, y: 0, sprite: { src: 'art:ui-' + icon, w: 24, h: 24 } },
    { name: label + ' Item Label', ui: true, anchor: 'left', x: 58, y: 0, text: { value: label, size: 17, color: '#ffffff', align: 'left', weight: '700' } },
  ] });
const page = (name, title, color) => ({ name: name, ui: true, anchor: 'center', x: 0, y: 0, stretch: 'both', margin: 0, layer: -1, shape: { type: 'rect', w: 400, h: 700, radius: 0, fill: color },
  behaviors: [{ type: 'uiShowIf', var: 'page', op: '=', value: title.toLowerCase(), whenUnset: false, anim: 'fade' }],
  children: [{ name: name + ' Title', ui: true, anchor: 'top', x: 0, y: 70, text: { value: title, size: 30, color: '#ffffff', weight: '900' } },
    { name: name + ' Hint', ui: true, anchor: 'top', x: 0, y: 110, text: { value: 'Add UI inside this page', size: 14, color: 'rgba(255,255,255,0.6)' } }] });
const backBtn = (name, anchor = 'top-left', x = 36, y = 40) => ({ name, ui: true, anchor, x, y, shape: { type: 'circle', r: 24, fill: 'rgba(255,255,255,0.14)' },
  behaviors: [{ type: 'uiBack', var: '', hide: true, fallback: '' }], children: [{ name: name + ' Icon', ui: true, anchor: 'center', x: 0, y: 0, sprite: { src: 'art:ui-back', w: 24, h: 24 } }] });
/** A full-screen page that slides in from the right when opened and back out when you go Back. */
const slidePage = (name, title, value, color, kids = []) => ({ name, ui: true, anchor: 'center', x: 0, y: 0, stretch: 'both', margin: 0, layer: -1, shape: { type: 'rect', w: 400, h: 700, radius: 0, fill: color },
  behaviors: [{ type: 'uiShowIf', var: 'page', op: '=', value, whenUnset: false, anim: 'slide (follows navigation)' }],
  children: [backBtn(name + ' Back'), { name: name + ' Title', ui: true, anchor: 'top', x: 0, y: 40, text: { value: title, size: 24, color: '#ffffff', weight: '900' } }, ...kids] });
const goBtn = (name, label, page, y, color = '#3a6ea5') => ({ name, ui: true, anchor: 'center', x: 0, y, shape: { type: 'rect', w: 240, h: 56, radius: 16, fill: color }, text: { value: label, size: 19, color: '#ffffff', weight: '800' },
  behaviors: [{ type: 'button', action: 'go to page', value: page, amount: 1, sound: 'click' }] });
const slide = (i, title, text, color) => ({ name: `Slide ${i + 1}`, ui: true, anchor: 'center', x: i * 340, y: -10, shape: { type: 'rect', w: 300, h: 230, radius: 22, fill: color },
  children: [{ name: `Slide ${i + 1} Title`, ui: true, anchor: 'center', x: 0, y: -30, text: { value: title, size: 26, color: '#ffffff', weight: '900' } },
    { name: `Slide ${i + 1} Text`, ui: true, anchor: 'center', x: 0, y: 20, text: { value: text, size: 15, color: 'rgba(255,255,255,0.85)', wrap: 240 } }] });
const iconBtn = (name, icon, anchor, x, y, msg) => ({ name, ui: true, anchor, x, y, shape: { type: 'circle', r: 24, fill: 'rgba(255,255,255,0.14)' },
  behaviors: [{ type: 'button', action: 'send message', value: msg, amount: 1, sound: 'click' }], children: [{ name: name + ' Icon', ui: true, anchor: 'center', x: 0, y: 0, sprite: { src: 'art:ui-' + icon, w: 24, h: 24 } }] });

